using JamunaBank.Procurement.API.Constants;using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Services.Interfaces;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace JamunaBank.Procurement.API.Controllers;
[ApiController,Authorize(Policy=AuthorizationPolicyNames.ProcurementTracker),Route("api/work-orders")]
public sealed class WorkOrderController(IWorkOrderService service):ControllerBase
{
 [HttpPost]public async Task<ActionResult<ApiResponse<StoredProcedureResult>>>Create(CreateWorkOrderRequest r,CancellationToken c)=>Map(await service.CreateAsync(r,c));[HttpPost("bulk-assign")]public async Task<ActionResult<ApiResponse<WorkOrderBatchResult>>>Bulk(CreateWorkOrderRequest r,CancellationToken c){var x=await service.BulkAssignAsync(r,c);return Ok(ApiResponse<WorkOrderBatchResult>.Ok(x,x.FailedCount==0?"Work Order assigned successfully.":x.SuccessfulCount==0?"Work Order assignment failed.":"Work Order assignment partially succeeded.",HttpContext.TraceIdentifier));}[HttpGet("{id:long}")]public async Task<ActionResult<ApiResponse<WorkOrderDto>>>Get(long id,CancellationToken c){var x=await service.GetAsync(id,c);return x is null?NotFound(ApiResponse<WorkOrderDto>.Fail("Work Order was not found.",[],HttpContext.TraceIdentifier)):Ok(ApiResponse<WorkOrderDto>.Ok(x,"Work Order loaded.",HttpContext.TraceIdentifier));}[HttpGet("by-requisition/{requisitionId:long}")]public async Task<ActionResult<ApiResponse<IReadOnlyList<WorkOrderDto>>>>ByRequisition(long requisitionId,CancellationToken c){var x=await service.GetByRequisitionAsync(requisitionId,c);return Ok(ApiResponse<IReadOnlyList<WorkOrderDto>>.Ok(x,"Work Orders loaded.",HttpContext.TraceIdentifier));}
 private ActionResult<ApiResponse<StoredProcedureResult>>Map(StoredProcedureResult?r){if(r is null)return StatusCode(500,ApiResponse<StoredProcedureResult>.Fail("No stored-procedure result was returned.",[],HttpContext.TraceIdentifier));return r.ResultCode switch{ResultCodes.Success=>Ok(ApiResponse<StoredProcedureResult>.Ok(r,"Work Order created and requisitions assigned.",HttpContext.TraceIdentifier)),ResultCodes.ValidationError=>BadRequest(ApiResponse<StoredProcedureResult>.Fail("Work Order is invalid.",[r.ResultMessage],HttpContext.TraceIdentifier)),ResultCodes.Conflict=>Conflict(ApiResponse<StoredProcedureResult>.Fail("Work Order conflicts with existing data.",[r.ResultMessage],HttpContext.TraceIdentifier)),_=>StatusCode(500,ApiResponse<StoredProcedureResult>.Fail("Work Order operation failed.",[r.ResultMessage],HttpContext.TraceIdentifier))};}
}
